//"'! # Three-Player Security Dilemma with Incomplete Information
//!
//! Models a circular fear structure: A fears B, B fears C, C fears A.
//! Demonstrates why bilateral arms control fails and how third-party
//! verification mechanisms restore cooperation.
//!
//! Also provides a triangulation estimator using three open-source
//! observables (news, AIS ship tracking, night-lights) to distinguish
//! genuine de-escalation from pause-to-rearm.

use std::collections::HashMap;
use std::fmt;

// ─────────────────────────────────────────────────────────────────
// PART I: GAME FORM
// ─────────────────────────────────────────────────────────────────

/// The three states in the circular fear structure.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum State {
    A,
    B,
    C,
}

/// Actions available to each state in each round.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum Action {
    /// Continue or increase arms buildup.
    Arm,
    /// Accept a bilateral arms-control agreement with the feared rival.
    BilateralControl,
    /// Accept a multilateral agreement with third-party verification.
    MultilateralVerification,
    /// Secretly rearm while publicly complying (available only under
    /// bilateral control — this is the deviation that unravels it).
    SecretRearm,
}

/// Private type capturing a state'"'s \"resolve\" — how much it values
/// security relative to economic welfare. This is the incomplete
/// information dimension: each state knows its own resolve but only
/// has a prior over others'.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ResolveType {
    /// High security-valuation; will arm unless it is very confident
    /// the rival will not.
    Hawk,
    /// Moderate; willing to cooperate under verification.
    Moderate,
    /// Low security-valuation; prefers economic payoff if any
    /// reasonable assurance of peace exists.
    Dove,
}

/// Qualitative payoff components.
#[derive(Debug, Clone, Copy)]
struct Payoff {
    /// Security benefit (higher = safer).
    security: i8,
    /// Economic welfare (higher = better off materially).
    economic: i8,
    /// Reputation / trust capital.
    reputation: i8,
}

impl Payoff {
    fn total(&self) -> i8 {
        self.security + self.economic + self.reputation
    }
}

impl fmt::Display for Payoff {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write"'!(
            f,
            "Payoff(sec={:+}, econ={:+}, rep={:+}, Σ={:+})",
            self.security, self.economic, self.reputation, self.total()
        )
    }
}

/// The circular fear relation: A→B, B→C, C→A.
fn feared_rival(state: State) -> State {
    match state {
        State::A => State::B,
        State::B => State::C,
        State::C => State::A,
    }
}

/// The "feared-by" relation (inverse): A is feared by C, B by A, C by B.
fn feared_by(state: State) -> State {
    match state {
        State::A => State::C,
        State::B => State::A,
        State::C => State::B,
    }
}

/// Qualitative payoff function.
///
/// Key structural assumptions:
/// 1. If you Arm and your rival also Arms → security dilemma: both pay
///    high arms costs, moderate security (nasty equilibrium).
/// 2. If you Arm and rival Cooperates → you gain security advantage,
///    rival is vulnerable.
/// 3. Bilateral control between (you, rival) ignores the *third* party.
///    Since C fears A, if A and B sign a bilateral deal, C'"'s uncertainty
///    about A's intentions *increases* (diverted resources could target C).
/// 4. Multilateral verification reduces incomplete information for all
///    three, making cooperation sustainable.
fn compute_payoff(
    actor: State,
    actor_action: Action,
    rival_action: Action,
    third_party_action: Action,
    actor_type: ResolveType,
    verification_active: bool,
) -> Payoff {
    let type_weight_security = match actor_type {
        ResolveType::Hawk => 3,
        ResolveType::Moderate => 2,
        ResolveType::Dove => 1,
    };

    // Base security: depends on relative arms posture.
    let base_security = match (actor_action, rival_action) {
        (Action::Arm, Action::Arm) => -2,           // arms race, costly
        (Action::Arm, Action::BilateralControl) => 3, // exploit cooperator
        (Action::Arm, Action::MultilateralVerification) => 2,
        (Action::Arm, Action::SecretRearm) => -1,
        (Action::BilateralControl, Action::Arm) => -3, // sucker payoff
        (Action::BilateralControl, Action::BilateralControl) => 2,
        (Action::BilateralControl, Action::MultilateralVerification) => 1,
        (Action::BilateralControl, Action::SecretRearm) => -2,
        (Action::MultilateralVerification, Action::Arm) => -1,
        (Action::MultilateralVerification, Action::BilateralControl) => 1,
        (Action::MultilateralVerification, Action::MultilateralVerification) => 3,
        (Action::MultilateralVerification, Action::SecretRearm) => 0,
        (Action::SecretRearm, Action::Arm) => 0,
        (Action::SecretRearm, Action::BilateralControl) => 4, // best deviation
        (Action::SecretRearm, Action::MultilateralVerification) => -2, // caught
        (Action::SecretRearm, Action::SecretRearm) => -1,
    };

    let security = base_security * type_weight_security;

    // Economic payoff: arms are costly, cooperation is beneficial.
    let base_economic = match actor_action {
        Action::Arm => -2,
        Action::BilateralControl => 1,
        Action::MultilateralVerification => 2,
        Action::SecretRearm => 0, // some arms cost, some economic benefit
    };
    let economic = base_economic * (5 - type_weight_security); // doves value econ more

    // Third-party effect: under bilateral control, the uninvolved third
    // party's behavior creates a negative externality on the actor.
    let third_party_penalty = match (actor_action, third_party_action) {
        (Action::BilateralControl, Action::Arm) => -2,
        (Action::BilateralControl, Action::SecretRearm) => -3,
        _ => 0,
    };

    // Reputation: verification builds trust; secret rearm discovery destroys it.
    let reputation = match (actor_action, verification_active) {
        (Action::MultilateralVerification, true) => 3,
        (Action::BilateralControl, false) => 0,
        (Action::SecretRearm, true) => -5,
        (Action::SecretRearm, false) => 1, // undetected
        _ => 0,
    };

    Payoff {
        security: security + third_party_penalty,
        economic,
        reputation,
    }
}

/// Information set for a state: what it observes before choosing.
struct InfoSet {
    /// Own type (known).
    own_type: ResolveType,
    /// Belief about rival's type (prior distribution).
    rival_type_belief: HashMap<ResolveType, f64>,
    /// Observation of rival's past actions (if any).
    observed_actions: Vec<(State, Action)>,
    /// Whether verification signals are available.
    verification_signal: bool,
}

