// ─────────────────────────────────────────────────────────────────
// PART IV: TRIANGULATION — CEASEFIRE VERIFICATION
// ─────────────────────────────────────────────────────────────────

/// Observable signals from open sources.
#[derive(Debug, Clone)]
struct ObservableSignals {
    /// Open news: frequency of escalatory vs de-escalatory language,
    /// diplomatic meeting reports, troop-movement allegations.
    /// Normalized: -1.0 (max escalatory) to +1.0 (max de-escalatory).
    news_sentiment: f64,

    /// AIS ship tracking: military/cargo vessel movements near
    /// conflict zone. Measured as change in vessel-count density
    /// relative to pre-ceasefire baseline.
    /// Negative = fewer ships (drawdown), Positive = buildup.
    ais_vessel_delta: f64,

    /// Electricity night-lights: radiance change in conflict zone.
    /// Proxy for economic activity / population movement /
    /// infrastructure damage. Measured as log-ratio vs baseline.
    /// Negative = darkening (conflict/depopulation), Positive = brightening.
    nightlight_delta: f64,
}

/// Hypothesis about ceasefire status.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CeasefireHypothesis {
    /// Genuine de-escalation: parties are disengaging.
    RealDeEscalation,
    /// Pause to rearm: ceasefire is tactical, not strategic.
    PauseToRearm,
}

/// Expected observable signatures under each hypothesis.
///
/// The triangulation logic:
///
/// REAL DE-ESCALATION:
///   - News: positive sentiment trend (diplomatic language, prisoner
///     exchanges, joint statements).
///   - AIS: military vessel drawdown, cargo patterns normalize to
///     pre-conflict routes.
///   - Night-lights: gradual brightening as civilians return, economic
///     activity resumes.
///   → Co-movement: all three move in the SAME direction (positive).
///
/// PAUSE TO REARM:
///   - News: mixed — public de-escalatory statements but continued
///     reports of military exercises, procurement, infrastructure work.
///   - AIS: military vessels REDISTRIBUTE (not decrease) — they move
///     to different ports, resupply patterns change. Total count may
///     stay flat or increase subtly.
///   - Night-lights: MILITARY zones brighten (activity) while civilian
///     zones stay dark (no return). Divergent spatial pattern.
///   → Co-movement: news says "peace" but AIS and night-lights show
///     persistent or redirected military activity. DIVERGENT signals.
struct TriangulationModel {
    /// Expected signal means under each hypothesis.
    real_deescalation: ExpectedSignals,
    pause_to_rearm: ExpectedSignals,
}

struct ExpectedSignals {
    news_mean: f64,
    news_var: f64,
    ais_mean: f64,
    ais_var: f64,
    nightlight_mean: f64,
    nightlight_var: f64,
}

impl TriangulationModel {
    fn new() -> Self {
        Self {
            real_deescalation: ExpectedSignals {
                news_mean: 0.6,
                news_var: 0.3,
                ais_mean: -0.5,     // vessel drawdown
                ais_var: 0.25,
                nightlight_mean: 0.4, // civilian recovery brightening
                nightlight_var: 0.3,
            },
            pause_to_rearm: ExpectedSignals {
                news_mean: 0.3,      // some de-escalatory rhetoric
                news_var: 0.5,       // but noisier / less consistent
                ais_mean: 0.1,       // roughly flat (redistribution, not drawdown)
                ais_var: 0.4,        // high variance (unusual patterns)
                nightlight_mean: -0.1, // minimal civilian return
                nightlight_var: 0.5,   // high spatial variance
            },
        }
    }

    /// Gaussian log-likelihood (up to constant) for an observation
    /// under a given expected signal.
    fn log_likelihood(observed: f64, mean: f64, variance: f64) -> f64 {
        let diff = observed - mean;
        -(diff * diff) / (2.0 * variance)
    }

    /// Compute log-posterior (unnormalized) for each hypothesis given
    /// the three observables. Assumes equal prior.
    fn score(&self, signals: &ObservableSignals) -> (f64, f64) {
        let ll_real = Self::log_likelihood(signals.news_sentiment, self.real_deescalation.news_mean, self.real_deescalation.news_var)
            + Self::log_likelihood(signals.ais_vessel_delta, self.real_deescalation.ais_mean, self.real_deescalation.ais_var)
            + Self::log_likelihood(signals.nightlight_delta, self.real_deescalation.nightlight_mean, self.real_deescalation.nightlight_var);

        let ll_rearm = Self::log_likelihood(signals.news_sentiment, self.pause_to_rearm.news_mean, self.pause_to_rearm.news_var)
            + Self::log_likelihood(signals.ais_vessel_delta, self.pause_to_rearm.ais_mean, self.pause_to_rearm.ais_var)
            + Self::log_likelihood(signals.nightlight_delta, self.pause_to_rearm.nightlight_mean, self.pause_to_rearm.nightlight_var);

        (ll_real, ll_rearm)
    }

    /// Classify and return confidence.
    fn classify(&self, signals: &ObservableSignals) -> (CeasefireHypothesis, f64) {
        let (ll_real, ll_rearm) = self.score(signals);
        let max_ll = ll_real.max(ll_rearm);
        let evidence_real = ll_real - max_ll;
        let evidence_rearm = ll_rearm - max_ll;

        // Convert to pseudo-probability via softmax.
        let prob_real = evidence_real.exp() / (evidence_real.exp() + evidence_rearm.exp());

        let hypothesis = if prob_real > 0.5 {
            CeasefireHypothesis::RealDeEscalation
        } else {
            CeasefireHypothesis::PauseToRearm
        };

        (hypothesis, prob_real.abs_diff(0.5) * 2.0) // confidence in [0, 1]
    }
}

/// Co-movement diagnostic: under real de-escalation, all three
/// observables should move in a consistent direction. Under
/// pause-to-rearm, they diverge.
fn co_movement_diagnostic(signals: &ObservableSignals) -> String {
    let news_positive = signals.news_sentiment > 0.2;
    let ais_drawdown = signals.ais_vessel_delta < -0.2;
    let lights_brightening = signals.nightlight_delta > 0.1;

    let consistent = (news_positive && ais_drawdown && lights_brightening)
        || (!news_positive && !ais_drawdown && !lights_brightening);

    if consistent {
        format!(
            "CO-MOVEMENT: CONSISTENT (all signals aligned)'"\\n\\
             → Supports single underlying process (either genuine peace or genuine escalation)\\n\\
             → News={:.2}, AIS={:.2}, Lights={:.2}\",
            signals.news_sentiment, signals.ais_vessel_delta, signals.nightlight_delta
        )
    } else {
        format"'!(
            "CO-MOVEMENT: DIVERGENT (signals tell different stories)'"\\n\\
             → News says: {}\\n\\
             → AIS says: {}\\n\\
             → Night-lights say: {}\\n\\
             → Divergence is the signature of PAUSE-TO-REARM: public narrative\\n\\
               diverges from material military/economic reality.\",
            if news_positive { \"de-escalation\" } else { \"tension\" },
            if ais_drawdown { \"drawdown\" } else if signals.ais_vessel_delta > 0.2 { \"buildup\" } else { \"redistribution/stasis\" },
            if lights_brightening { \"recovery\" } else { \"stagnation/darkening\" }
        )
    }
}

