//"'! # Three-Player Security Dilemma with Incomplete Information
//!
//! Models a circular fear structure: A fears B, B fears C, C fears A.
//! Demonstrates why bilateral arms control fails and how third-party
//! verification mechanisms restore cooperation.
//!
//! Also provides a triangulation estimator using three open-source
//! observables (news, AIS ship tracking, night-lights) to distinguish
//! genuine de-escalation from pause-to-rearm.

use std::collections::HashMap;
use std::fmt;

// ─────────────────────────────────────────────────────────────────
// PART I: GAME FORM
// ─────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum State { A, B, C }

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum Action {
    Arm,
    BilateralControl,
    MultilateralVerification,
    SecretRearm,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ResolveType { Hawk, Moderate, Dove }

#[derive(Debug, Clone, Copy)]
struct Payoff {
    security: i8,
    economic: i8,
    reputation: i8,
}

impl Payoff {
    fn total(&self) -> i8 {
        self.security + self.economic + self.reputation
    }
}

impl fmt::Display for Payoff {
    fn fmt(&self, f: &mut fmt::Formatter<'"'_>) -> fmt::Result {
        write"'!(
            f,
            "Payoff(sec={:+}, econ={:+}, rep={:+}, total={:+})",
            self.security, self.economic, self.reputation, self.total()
        )
    }
}

fn feared_rival(state: State) -> State {
    match state {
        State::A => State::B,
        State::B => State::C,
        State::C => State::A,
    }
}

/// Qualitative payoff function.
///
/// Key structural assumptions:
/// 1. Arm vs Arm → security dilemma: costly, moderate security.
/// 2. Arm vs Cooperate → exploit the cooperator.
/// 3. Bilateral control ignores the third party → diversion suspicion.
/// 4. Multilateral verification reduces incomplete information for all three.
fn compute_payoff(
    actor: State,
    actor_action: Action,
    rival_action: Action,
    third_party_action: Action,
    actor_type: ResolveType,
    verification_active: bool,
) -> Payoff {
    let _ = actor; // structural; payoff depends on relative actions
    let type_weight_security: i8 = match actor_type {
        ResolveType::Hawk => 3,
        ResolveType::Moderate => 2,
        ResolveType::Dove => 1,
    };

    let base_security: i8 = match (actor_action, rival_action) {
        (Action::Arm, Action::Arm) => -2,
        (Action::Arm, Action::BilateralControl) => 3,
        (Action::Arm, Action::MultilateralVerification) => 2,
        (Action::Arm, Action::SecretRearm) => -1,
        (Action::BilateralControl, Action::Arm) => -3,
        (Action::BilateralControl, Action::BilateralControl) => 2,
        (Action::BilateralControl, Action::MultilateralVerification) => 1,
        (Action::BilateralControl, Action::SecretRearm) => -2,
        (Action::MultilateralVerification, Action::Arm) => -1,
        (Action::MultilateralVerification, Action::BilateralControl) => 1,
        (Action::MultilateralVerification, Action::MultilateralVerification) => 3,
        (Action::MultilateralVerification, Action::SecretRearm) => 0,
        (Action::SecretRearm, Action::Arm) => 0,
        (Action::SecretRearm, Action::BilateralControl) => 4,
        (Action::SecretRearm, Action::MultilateralVerification) => -2,
        (Action::SecretRearm, Action::SecretRearm) => -1,
    };

    let security = base_security * type_weight_security;

    let base_economic: i8 = match actor_action {
        Action::Arm => -2,
        Action::BilateralControl => 1,
        Action::MultilateralVerification => 2,
        Action::SecretRearm => 0,
    };
    let economic = base_economic * (5 - type_weight_security);

    let third_party_penalty: i8 = match (actor_action, third_party_action) {
        (Action::BilateralControl, Action::Arm) => -2,
        (Action::BilateralControl, Action::SecretRearm) => -3,
        _ => 0,
    };

    let reputation: i8 = match (actor_action, verification_active) {
        (Action::MultilateralVerification, true) => 3,
        (Action::BilateralControl, false) => 0,
        (Action::SecretRearm, true) => -5,
        (Action::SecretRearm, false) => 1,
        _ => 0,
    };

    Payoff {
        security: security + third_party_penalty,
        economic,
        reputation,
    }
}

struct InfoSet {
    own_type: ResolveType,
    rival_type_belief: HashMap<ResolveType, f64>,
    observed_actions: Vec<(State, Action)>,
    verification_signal: bool,
}

// ─────────────────────────────────────────────────────────────────
// PART II: WHY BILATERAL CONTROL FAILS
// ─────────────────────────────────────────────────────────────────

fn analyze_bilateral_failure() {
